// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import {IFactory} from "./../interfaces/IFactory.sol";
import {FacilityRegistry} from "./../Facility/FacilityRegistry.sol";
import {InitialGateway} from "./../data_structs.sol";
import {FacilityAdded , FacilityCreated} from "./../Events.sol";

contract PlatformFactory is IFactory {
    address public owner;
    string[] public factory_docs;

    struct Document {
        string cid;         // IPFS/Arweave Hash (e.g. "QmXoypizjW3WknFiJnKLwHCnL72vedxjQkDDP1mXWo6uco")
        string docType;     // "SOP", "DATASHEET", "COMPLIANCE_RULE", "LEGAL_GUIDE"
        string title;       // Human-readable title
        uint256 uploadedAt;
    }

    struct FacilityMeta {
        address facilityAddress;
        string name;
        string location;
        string sectorType;  // e.g. "Chemical", "Hydroelectric", "Nuclear" , "Solar"
        uint256 createdAt;
        bool isActive;
        string[] docCids;    // Quick lookup list of active CIDs
    }

    // Mappings
    address[] public deployedFacilities;
    mapping(address => FacilityMeta) public facilityInfo;

    mapping(address => address[]) public current_inspectors; //for each facility, it may or may not have an inspector
    
    // facilityAddress => (CID => Document)
    mapping(address => mapping(string => Document)) public facilityDocs;

    // Events
    event DocumentAdded(address indexed facilityAddress, string cid, string docType);
    event DocumentRevoked(address indexed facilityAddress, string cid);

    modifier onlyOwner() {
        require(msg.sender == owner, "Factory: caller is not the owner");
        _;
    }

    modifier onlyFacilityAdmin(address _facility) {
        // Enforces that only the creator/admin of that specific facility (or platform owner) can attach docs
        require(msg.sender == owner || msg.sender == facilityInfo[_facility].facilityAddress, "Unauthorized");
        _;
    }

    constructor(string[] memory platform_docs) {
        owner = msg.sender;
        factory_docs = platform_docs;
    }


    /**
     * @notice Registers an independently deployed FacilityRegistry into the Platform Factory
     * @dev Enforces caller ownership check and contract interface validation
     */
    function addExistingFacility(
        address _facilityContract,
        string calldata _location,
        string calldata _sectorType
    ) external {
        require(_facilityContract != address(0), "Invalid contract address");
        require(facilityInfo[_facilityContract].facilityAddress == address(0), "Facility already registered");

        // 1. Interface Validation: Call facilityName() via try/catch
        string memory retrievedName;
        try FacilityRegistry(payable(_facilityContract)).facilityName() returns (string memory name) {
            require(bytes(name).length > 0, "Invalid facility name");
            retrievedName = name;
        } catch {
            revert("Target address is not a valid FacilityRegistry instance");
        }

        // 2. Ownership Verification: Ensure msg.sender is the Admin of the target facility
        try FacilityRegistry(payable(_facilityContract)).admin() returns (address facilityAdmin) {
            require(facilityAdmin == msg.sender, "Caller is not the admin of target facility");
        } catch {
            revert("Failed to verify facility admin");
        }

        // 3. Register in Factory directory
        deployedFacilities.push(_facilityContract);

        FacilityMeta storage meta = facilityInfo[_facilityContract];
        meta.facilityAddress = _facilityContract;
        meta.name = retrievedName;
        meta.location = _location;
        meta.sectorType = _sectorType;
        meta.createdAt = block.timestamp;
        meta.isActive = true;

        emit FacilityAdded(_facilityContract, retrievedName, msg.sender);
    }



    function addFacilityDocument(
        address _facility, 
        string calldata _cid, 
        string calldata _docType, 
        string calldata _title
    ) external onlyFacilityAdmin(_facility) {
        require(bytes(_cid).length > 0, "Invalid CID");
        
        // Save document metadata
        facilityDocs[_facility][_cid] = Document({
            cid: _cid,
            docType: _docType,
            title: _title,
            uploadedAt: block.timestamp
        });

        // Append to facility CIDs array
        facilityInfo[_facility].docCids.push(_cid);

        emit DocumentAdded(_facility, _cid, _docType);
    }

    /**
     * @notice Replace or revoke an outdated document/rule set CID
     */
    function replaceFacilityDocument(
        address _facility, 
        string calldata _oldCid, 
        string calldata _newCid, 
        string calldata _newDocType, 
        string calldata _newTitle
    ) external onlyFacilityAdmin(_facility) {
        // 1. Revoke / remove old CID from array
        _removeCid(_facility, _oldCid);
        emit DocumentRevoked(_facility, _oldCid);

        // 2. Add new CID
        facilityDocs[_facility][_newCid] = Document({
            cid: _newCid,
            docType: _newDocType,
            title: _newTitle,
            uploadedAt: block.timestamp
        });
        facilityInfo[_facility].docCids.push(_newCid);

        emit DocumentAdded(_facility, _newCid, _newDocType);
    }

    // Helper internal array cleanup
    function _removeCid(address _facility, string memory _targetCid) internal {
        string[] storage cids = facilityInfo[_facility].docCids;
        uint256 length = cids.length;
        for (uint256 i = 0; i < length; i++) {
            if (keccak256(bytes(cids[i])) == keccak256(bytes(_targetCid))) {
                cids[i] = cids[length - 1];
                cids.pop();
                break;
            }
        }
    }

    // --- View Getters for UI ---

    function getFacilityCids(address _facility) external view returns (string[] memory) {
        return facilityInfo[_facility].docCids;
    }

    function getFacilityCount() external view returns (uint256) {
        return deployedFacilities.length;
    }

    function getFactoryDocs() external view returns (string[] memory) {
        return factory_docs;
    }
}

