// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./FacilityAccess.sol";
import "./FacilityRelayers.sol";
import "./FacilityKeys.sol";
import "./FacilityPolicy.sol";
import {InitialGateway} from "./../data_structs.sol";

contract FacilityRegistry is 
    FacilityAccess, 
    FacilityRelayers, 
    FacilityKeys, 
    FacilityPolicy 
{
    
    constructor(
        address _admin, 
        string memory _facilityName,
        address[] memory _initialRelayers,
        InitialGateway[] memory _gateways
    ) {
        require(_admin != address(0), "Invalid Admin");

        factory = msg.sender;
        admin = _admin;
        facilityName = _facilityName;
        userRoles[_admin] = Role.ADMIN;

        // 1. Register Initial Relayers
        for (uint256 i = 0; i < _initialRelayers.length; i++) {
            if (_initialRelayers[i] != address(0)) {
                registerRelayer(_initialRelayers[i]);
            }
        }

        // 2. Register Initial Gateways
        for (uint256 j = 0; j < _gateways.length; j++) {
            // Use explicitly designated relayer if provided; otherwise fallback to round-robin
            address targetRelayer = _gateways[j].relayer != address(0) 
                ? _gateways[j].relayer 
                : (_initialRelayers.length > 0 ? _initialRelayers[j % _initialRelayers.length] : address(0));

            require(targetRelayer != address(0), "No relayer available for gateway");
            
            assignGatewayToRelayer(_gateways[j].id, _gateways[j].key, targetRelayer);
        }
    }

    receive() external payable {
        revert("Direct HBAR transfers rejected");
    }
}

