// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./FacilityStorageBase.sol";
import {IFacilityKeys} from "./../interfaces/IFacility.sol";
import "./../Events.sol";

abstract contract FacilityKeys is FacilityStorageBase, IFacilityKeys {

    /**
     * @notice Atomic Gateway Key Rotation
     * @dev Checks rotation cadence: if performed out-of-cadence, flags payload as anomalous
     */
    function rotateKey(string calldata gatewayId, address newPublicKey) external notInEmergency onlyAuthorizedRelayer(gatewayId) {
        require(newPublicKey != address(0), "Invalid Key");
        
        KeyRecord storage record = gatewayKeys[gatewayId];
        address oldKey = record.publicKey;
        
        // Cadence Check: Is this rotation early or unexpected?
        CadencePolicy memory policy = gatewayPolicies[gatewayId];
        bool isAnomalous = false;

        if (record.rotatedAt > 0 && policy.expectedInterval > 0) {
            uint256 timeDelta = block.timestamp - record.rotatedAt;
            // If rotated before expected window minus grace period -> Cadence Anomaly Flagged
            if (timeDelta < (policy.expectedInterval - policy.gracePeriod)) {
                isAnomalous = true;
            }
        }

        // Overwrite active storage (implicit revocation of old key)
        record.publicKey = newPublicKey;
        record.rotatedAt = block.timestamp;
        record.sequenceNumber += 1;

        emit KeyRotated(gatewayId, oldKey, newPublicKey, isAnomalous, block.timestamp);
    }

    function getGatewayKey(string calldata gatewayId) external view returns (address) {
        return gatewayKeys[gatewayId].publicKey;
    }
}

