abstract contract FacilityAccess is FacilityStorageBase, IFacilityAccess {
    
    function setRole(address account, Role role) external onlyAdmin {
        require(account != address(0), "Invalid address");
        userRoles[account] = role;
        emit RoleUpdated(account, role);
    }

    function getUserRole(address account) external view returns (Role) {
        if (account == admin) return Role.ADMIN;
        if (userRoles[account] == Role(0)) return Role.NONE;
        return userRoles[account];
    }

    function toggleEmergencyOverride(bool active) external onlyAdmin {
        emergencyOverride = active;
        emit EmergencyOverrideToggled(active, msg.sender);
    }
}

