// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import {Role, KeyRecord, CadencePolicy , Gateway} from "./../data_structs.sol";



abstract contract FacilityStorageBase {

    address public factory;
    address public admin;
    string public facilityName;
    bool public emergencyOverride;

    // Mapping: Account => Assigned Role
    mapping(address => Role) public userRoles;

    // Relayer Core Mappings
    mapping(address => bool) public isRelayer;
    mapping(address => string[]) public relayerGateways; // Relayer => Array of Gateway IDs
    
    // Gateway Core Mappings
    mapping(string => Gateway) public gateways;         // Gateway ID => Gateway Struct
    mapping(string => CadencePolicy) public gatewayPolicies;
    mapping(string => KeyRecord) public gatewayKeys;

    // --- Modifiers ---
    modifier onlyAdmin() {
        require(msg.sender == admin || userRoles[msg.sender] == Role.ADMIN, "Auth: Not Admin");
        _;
    }

    modifier onlyAuthorizedRelayer(string memory gatewayId) {
        require(userRoles[msg.sender] == Role.RELAYER, "Auth: Not a registered Relayer");
        require(gateways[gatewayId].managingRelayer == msg.sender, "Auth: Relayer not assigned to this Gateway");
        _;
    }
    modifier notInEmergency() {
        require(!emergencyOverride, "State: Emergency Lockdown Active");
        _;
    }
}

