// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./FacilityStorageBase.sol";
import {IFacilityRelayers} from "./../interfaces/IFacility.sol";
import {RelayerRegistered , GatewayAssignedToRelayer , GatewayReassigned , RelayerRemoved} from "./../Events.sol";

abstract contract FacilityRelayers is FacilityStorageBase, IFacilityRelayers {

    /**
     * @notice Register a new Relayer node
     */
    function registerRelayer(address _relayer) public onlyAdmin {
        require(_relayer != address(0), "Invalid Relayer Address");
        require(!isRelayer[_relayer], "Relayer already registered");

        isRelayer[_relayer] = true;
        userRoles[_relayer] = Role.RELAYER;

        emit RelayerRegistered(_relayer, "Facility Relayer Node");
    }

    /**
     * @notice Remove a Relayer and unassign its associated gateways
     */
    function removeRelayer(address _relayer) external onlyAdmin {
        require(isRelayer[_relayer], "Address is not a registered Relayer");

        isRelayer[_relayer] = false;
        userRoles[_relayer] = Role.NONE;

        // Unassign all managed gateways
        string[] memory managedIds = relayerGateways[_relayer];
        for (uint256 i = 0; i < managedIds.length; i++) {
            gateways[managedIds[i]].managingRelayer = address(0);
        }
        delete relayerGateways[_relayer];

        emit RelayerRemoved(_relayer);
    }

    /**
     * @notice Assign a new Gateway to a specific Relayer
     */
    function assignGatewayToRelayer(
        string memory _gatewayId, 
        address _initialKey, 
        address _relayer
    ) public onlyAdmin {
        require(isRelayer[_relayer], "Target address is not an authorized Relayer");
        require(_initialKey != address(0), "Invalid Initial Gateway Key");
        require(!gateways[_gatewayId].isActive, "Gateway already exists");

        // Populate Gateway Struct
        gateways[_gatewayId] = Gateway({
            gatewayId: _gatewayId,
            activeKey: _initialKey,
            managingRelayer: _relayer,
            isActive: true,
            registeredAt: block.timestamp
        });

        // Add Gateway ID to Relayer's managed list
        relayerGateways[_relayer].push(_gatewayId);

        emit GatewayAssignedToRelayer(_gatewayId, _relayer);
    }

    /**
     * @notice Reassign an existing Gateway from one Relayer to another
     */
    function reassignGatewayRelayer(string calldata _gatewayId, address _newRelayer) external onlyAdmin {
        require(gateways[_gatewayId].isActive, "Gateway does not exist");
        require(isRelayer[_newRelayer], "New address is not a registered Relayer");

        address oldRelayer = gateways[_gatewayId].managingRelayer;
        require(oldRelayer != _newRelayer, "Gateway already managed by this Relayer");

        // Update Gateway Struct
        gateways[_gatewayId].managingRelayer = _newRelayer;

        // Remove Gateway ID from Old Relayer's array
        _removeGatewayFromRelayerArray(oldRelayer, _gatewayId);

        // Append to New Relayer's array
        relayerGateways[_newRelayer].push(_gatewayId);

        emit GatewayReassigned(_gatewayId, oldRelayer, _newRelayer);
    }

    // --- Helpers & Views ---

    function _removeGatewayFromRelayerArray(address _relayer, string memory _targetId) internal {
        string[] storage list = relayerGateways[_relayer];
        uint256 length = list.length;
        for (uint256 i = 0; i < length; i++) {
            if (keccak256(bytes(list[i])) == keccak256(bytes(_targetId))) {
                list[i] = list[length - 1];
                list.pop();
                break;
            }
        }
    }

    function getRelayerGateways(address _relayer) external view returns (string[] memory) {
        return relayerGateways[_relayer];
    }

    function getGatewayInfo(string calldata _gatewayId) external view returns (Gateway memory) {
        return gateways[_gatewayId];
    }

    function banGateway(string calldata _gatewayId) external {
        require(msg.sender == gateways[_gatewayId].managingRelayer || msg.sender == admin , "You have no authority to ban this gateway");
        delete gateways[_gatewayId];
        _removeGatewayFromRelayerArray(msg.sender, _gatewayId);
    }
}

